"""Semantic version helpers."""


def parse(version: str) -> tuple[int, int, int]:
    """Split "MAJOR.MINOR.PATCH" into three integers."""
    major, minor, patch = (int(part) for part in version.split("."))
    return major, minor, patch


def is_stable(version: str) -> bool:
    """True for versions 1.0.0 and later."""
    return parse(version)[0] >= 1


def bump(version: str, part: str) -> str:
    """Return the next version, incrementing "major", "minor", or "patch"."""
    major, minor, patch = parse(version)
    if part == "major":
        return f"{major + 1}.0.0"
    if part == "minor":
        return f"{major}.{minor + 1}.0"
    if part == "patch":
        return f"{major}.{minor}.{patch + 1}"
    raise ValueError(f"unknown part {part!r}")


def compare(a: str, b: str) -> int:
    """Return -1, 0, or 1 as version a is lower than, equal to, or higher than b."""
    pa, pb = parse(a), parse(b)
    return (pa > pb) - (pa < pb)


def is_newer(a: str, b: str) -> bool:
    """True when version a is higher than version b."""
    return compare(a, b) > 0

