from shipit.semver import bump, compare, parse


def test_parse():
    assert parse("2.3.1") == (2, 3, 1)


def test_bump():
    assert bump("2.3.1", "patch") == "2.3.2"
    assert bump("2.3.1", "minor") == "2.4.0"
    assert bump("2.3.1", "major") == "3.0.0"


def test_compare():
    assert compare("2.10.0", "2.9.9") == 1
    assert compare("1.0.0", "1.0.0") == 0

