"""Release note formatting."""


def heading(version: str, date: str) -> str:
    """Markdown heading for one release section."""
    return f"## {version} ({date})"


def bullet_list(lines: list[str]) -> str:
    """Format change descriptions as a Markdown bullet list."""
    return "\n".join(f"- {line}" for line in lines)


def release_section(version: str, date: str, lines: list[str]) -> str:
    """A full release section: the heading, a blank line, then the bullets."""
    return heading(version, date) + "\n\n" + bullet_list(lines)

